# Corpus of plots from ggplot2's examples and tests (T0.5). The files in
# corpus/ are generated by tools/extract-corpus.R; each corpus_block() is one
# Rd page or one upstream test_that(), and each .plot() inside it is a plot
# checked with expect_build_equal(). When ggplot2 fails to build a plot,
# alot must fail too, with the same error message.
#
# Allow-listed plots (corpus-allow.R) are evaluated, so later setup still
# works, but not checked.

skip_on_cran()
library(ggplot2)

corpus_dir <- test_path("corpus")
corpus_allow <- source(test_path("corpus-allow.R"), local = TRUE)$value %||% character()
corpus_counts <- new.env()
corpus_counts$checked <- 0L
corpus_counts$allowed <- 0L
corpus_counts$skipped <- 0L
corpus_ids <- character()

expect_corpus_equal <- function(p) {
  set.seed(1)
  ref <- tryCatch(ggplot2::ggplot_build(p), error = identity)
  if (!inherits(ref, "error")) {
    return(expect_build_equal(p))
  }
  set.seed(1)
  out <- tryCatch(alot_build(p), error = identity)
  expect_s3_class(out, "error")
  if (inherits(out, "error")) {
    expect_equal(conditionMessage(out), conditionMessage(ref))
  }
}

# Run one corpus block in a fresh function frame, so local_*() helpers in the
# upstream code have a frame to attach to. The frame's parent is ggplot2's
# namespace because upstream tests use internal functions.
run_corpus_block <- function(code) {
  env <- new.env(parent = asNamespace("ggplot2"))
  sys.source(file.path(corpus_dir, "_helpers.R"), envir = env)
  env$.plot <- function(id, expr) {
    corpus_ids <<- c(corpus_ids, id)
    p <- expr
    if (id %in% names(corpus_allow)) {
      corpus_counts$allowed <- corpus_counts$allowed + 1L
      return(invisible(p))
    }
    corpus_counts$checked <- corpus_counts$checked + 1L
    expect_corpus_equal(p)
    invisible(p)
  }
  runner <- rlang::new_function(list(), code, env)

  old_opts <- options()
  old_theme <- ggplot2::theme_get()
  on.exit({
    options(old_opts)
    ggplot2::theme_set(old_theme)
  })
  set.seed(1)
  tryCatch(
    suppressWarnings(suppressMessages(runner())),
    packageNotFoundError = function(e) {
      corpus_counts$skipped <- corpus_counts$skipped + 1L
      skip(conditionMessage(e))
    },
    skip = function(e) {
      corpus_counts$skipped <- corpus_counts$skipped + 1L
      skip(conditionMessage(e))
    }
  )
}

corpus_files <- list.files(corpus_dir, "\\.R$")
corpus_files <- corpus_files[!startsWith(corpus_files, "_")]
# ALOT_CORPUS, a regex on file names, runs a subset, e.g. "geom-bar|geom_point".
corpus_filter <- Sys.getenv("ALOT_CORPUS")
if (nzchar(corpus_filter)) {
  corpus_files <- grep(corpus_filter, corpus_files, value = TRUE)
}
for (file in corpus_files) {
  for (block in parse(file.path(corpus_dir, file), keep.source = FALSE, encoding = "UTF-8")) {
    stopifnot(identical(block[[1]], quote(corpus_block)))
    local({
      code <- block[[3]]
      test_that(paste("corpus:", block[[2]]), run_corpus_block(code))
    })
  }
}

test_that("every allow-listed plot is in the corpus", {
  skip_if(nzchar(corpus_filter), "ALOT_CORPUS runs a subset")
  expect_equal(setdiff(names(corpus_allow), corpus_ids), character())
})

message(sprintf(
  "Corpus: %d plots checked, %d allow-listed, %d blocks skipped (missing package or skip()).",
  corpus_counts$checked, corpus_counts$allowed, corpus_counts$skipped
))
